1	export type Cell = [number, number];
2	
3	const NEIGHBOR_OFFSETS: Cell[] = [
4	  [-1, -1],
5	  [-1, 0],
6	  [-1, 1],
7	  [0, -1],
8	  [0, 1],
9	  [1, -1],
10	  [1, 0],
11	  [1, 1],
12	];
13	
14	const neighborsOf = ([x, y]: Cell): Cell[] =>
15	  NEIGHBOR_OFFSETS.map(([dx, dy]): Cell => [x + dx, y + dy]);
16	
17	const identityOf = ([x, y]: Cell): string => `${x},${y}`;
18	
19	const isLive = (cell: Cell, liveIdentities: Set<string>): boolean =>
20	  liveIdentities.has(identityOf(cell));
21	
22	const countLiveNeighbors = (cell: Cell, liveIdentities: Set<string>): number =>
23	  neighborsOf(cell).filter((neighbor) => isLive(neighbor, liveIdentities)).length;
24	
25	const withoutDuplicates = (cells: Cell[]): Cell[] => [
26	  ...new Map(cells.map((cell) => [identityOf(cell), cell])).values(),
27	];
28	
29	const candidatesForNextGeneration = (liveCells: Cell[]): Cell[] =>
30	  withoutDuplicates([...liveCells, ...liveCells.flatMap(neighborsOf)]);
31	
32	const SURVIVAL_NEIGHBOR_COUNTS = [2, 3];
33	const BIRTH_NEIGHBOR_COUNT = 3;
34	
35	const isAliveNextGeneration = (
36	  cell: Cell,
37	  liveIdentities: Set<string>,
38	): boolean => {
39	  const liveNeighbors = countLiveNeighbors(cell, liveIdentities);
40	  return isLive(cell, liveIdentities)
41	    ? SURVIVAL_NEIGHBOR_COUNTS.includes(liveNeighbors)
42	    : liveNeighbors === BIRTH_NEIGHBOR_COUNT;
43	};
44	
45	export const nextGeneration = (liveCells: Cell[]): Cell[] => {
46	  const liveIdentities = new Set(liveCells.map(identityOf));
47	  return candidatesForNextGeneration(liveCells).filter((cell) =>
48	    isAliveNextGeneration(cell, liveIdentities),
49	  );
50	};
